css:
.auction-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #0a0e1a 0%, #0f1424 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e8eaed;
}

.auction-sim-container *,
.auction-sim-container *::before,
.auction-sim-container *::after {
    box-sizing: border-box;
}

.auction-sim-header {
    background: linear-gradient(135deg, #141b2e 0%, #1c2440 100%);
    border-radius: 6px;
    padding: 32px 36px;
    margin-bottom: 24px;
    border-top: 3px solid #d4af37;
    position: relative;
    overflow: hidden;
}

.auction-sim-header::after {
    content: '';
    position: absolute;
    top: 0; right: 0;
    width: 220px; height: 100%;
    background: radial-gradient(circle at top right, rgba(212,175,55,0.18), transparent 70%);
    pointer-events: none;
}

.auction-sim-brand {
    color: #d4af37;
    font-size: 0.72rem;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    margin-bottom: 14px;
    font-weight: 600;
}

.auction-sim-header h1 {
    color: #f6e7b6;
    font-size: 1.75rem;
    font-weight: 600;
    margin: 0 0 10px 0;
    letter-spacing: 0.01em;
}

.auction-sim-subtitle {
    color: #9aa3b8;
    font-size: 0.95rem;
    font-style: italic;
}

.auction-sim-meta-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 22px;
    padding: 16px 22px;
    background: #141b2e;
    border-radius: 4px;
    border-left: 3px solid #d4af37;
}

.auction-sim-period-counter {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.auction-sim-meta-label {
    color: #8b95a8;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
}

.auction-sim-meta-value {
    color: #f6e7b6;
    font-size: 1.4rem;
    font-weight: 600;
}

.auction-sim-format-badge {
    background: rgba(212,175,55,0.12);
    color: #d4af37;
    border: 1px solid #5a4a1f;
    padding: 8px 18px;
    border-radius: 999px;
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.auction-sim-format-design {
    background: rgba(192,57,43,0.18);
    color: #f4a892;
    border-color: #7a3320;
}

.auction-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}

.auction-sim-kpi-card {
    background: #141b2e;
    border: 1px solid #2a3654;
    border-radius: 6px;
    padding: 22px 20px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.25s ease, transform 0.2s ease;
}

.auction-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 4px; height: 100%;
    background: #2a3654;
    transition: background 0.25s ease;
}

.auction-sim-kpi-card:hover {
    border-color: #3a4870;
    transform: translateY(-2px);
}

.auction-sim-kpi-card:hover::before {
    background: #d4af37;
}

.auction-sim-kpi-accent {
    background: linear-gradient(135deg, #1c2440 0%, #2a1f44 100%);
    border-color: #4a3a6a;
}

.auction-sim-kpi-accent::before {
    background: #d4af37;
}

.auction-sim-kpi-label {
    color: #8b95a8;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
}

.auction-sim-kpi-value {
    color: #f6e7b6;
    font-size: 2rem;
    font-weight: 700;
    line-height: 1.1;
}

.auction-sim-kpi-accent .auction-sim-kpi-value {
    color: #d4af37;
}

.auction-sim-briefing {
    background: #141b2e;
    border: 1px solid #2a3654;
    border-radius: 6px;
    padding: 26px 28px;
    margin-bottom: 24px;
    border-left: 3px solid #c0392b;
}

.auction-sim-briefing-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 14px;
}

.auction-sim-briefing-header h2 {
    color: #f6e7b6;
    font-size: 1.25rem;
    font-weight: 600;
    margin: 0;
}

.auction-sim-anchor {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    text-align: right;
}

.auction-sim-anchor-label {
    color: #8b95a8;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
}

#roundAnchor {
    color: #d4af37;
    font-size: 0.85rem;
    font-weight: 600;
}

.auction-sim-briefing-body {
    color: #c4cad6;
    font-size: 0.95rem;
    line-height: 1.6;
    margin-bottom: 14px;
}

.auction-sim-briefing-body strong {
    color: #f6e7b6;
}

.auction-sim-briefing-body em {
    color: #d4af37;
    font-style: italic;
}

.auction-sim-equilibrium-note {
    background: rgba(212,175,55,0.07);
    border-left: 3px solid #d4af37;
    border-radius: 0 4px 4px 0;
    padding: 14px 18px;
    color: #d8ddea;
    font-size: 0.9rem;
    line-height: 1.55;
}

.auction-sim-equilibrium-note strong {
    color: #d4af37;
}

.auction-sim-controls {
    background: #141b2e;
    border: 1px solid #2a3654;
    border-radius: 6px;
    padding: 24px 28px;
    margin-bottom: 24px;
}

.auction-sim-controls h3 {
    color: #f6e7b6;
    font-size: 1.05rem;
    font-weight: 600;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #2a3654;
    letter-spacing: 0.02em;
}

.auction-sim-input-row {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 18px;
}

.auction-sim-input-row label {
    color: #c4cad6;
    font-size: 0.9rem;
    font-weight: 500;
}

.auction-sim-controls input[type="number"] {
    background: #0a0e1a;
    border: 1px solid #2a3654;
    color: #f6e7b6;
    font-size: 1.15rem;
    font-weight: 600;
    border-radius: 4px;
    padding: 10px 14px;
    width: 100%;
    max-width: 280px;
    transition: border-color 0.2s ease;
}

.auction-sim-controls input[type="number"]:focus {
    outline: none;
    border-color: #d4af37;
    box-shadow: 0 0 0 2px rgba(212,175,55,0.15);
}

.auction-sim-bidder-row {
    margin-top: 10px;
    padding-top: 16px;
    border-top: 1px dashed #2a3654;
}

.auction-sim-bidder-label {
    display: block;
    color: #8b95a8;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
}

.auction-sim-bidder-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}

.auction-sim-bidder-chip {
    background: rgba(255,255,255,0.04);
    border: 1px solid #2a3654;
    color: #9aa3b8;
    padding: 6px 14px;
    border-radius: 999px;
    font-size: 0.8rem;
}

.auction-sim-design-panel .auction-sim-design-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    align-items: center;
    padding: 14px 0;
    border-bottom: 1px solid #1f2840;
}

.auction-sim-design-panel .auction-sim-design-row:last-child {
    border-bottom: none;
}

.auction-sim-design-panel label {
    color: #c4cad6;
    font-size: 0.92rem;
    font-weight: 500;
    line-height: 1.4;
}

.auction-sim-design-select {
    background: #0a0e1a;
    border: 1px solid #2a3654;
    color: #f6e7b6;
    border-radius: 4px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.92rem;
}

.auction-sim-design-select option {
    background: #141b2e;
    color: #f6e7b6;
}

.auction-sim-design-select:focus {
    outline: none;
    border-color: #d4af37;
    box-shadow: 0 0 0 2px rgba(212,175,55,0.15);
}

.auction-sim-action-row {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    margin-bottom: 28px;
}

.auction-sim-submit-btn {
    background: linear-gradient(135deg, #d4af37 0%, #b8901f 100%);
    color: #0a0e1a;
    border: none;
    padding: 12px 32px;
    font-size: 0.95rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    border-radius: 4px;
    transition: transform 0.18s ease, box-shadow 0.18s ease;
    cursor: pointer;
}

.auction-sim-submit-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 18px rgba(212,175,55,0.25);
    color: #0a0e1a;
}

.auction-sim-undo-btn {
    background: transparent;
    color: #9aa3b8;
    border: 1px solid #2a3654;
    padding: 12px 22px;
    font-size: 0.85rem;
    border-radius: 4px;
    transition: border-color 0.2s ease, color 0.2s ease;
    cursor: pointer;
}

.auction-sim-undo-btn:hover {
    border-color: #d4af37;
    color: #d4af37;
}

.auction-sim-history-block {
    background: #141b2e;
    border: 1px solid #2a3654;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 24px;
}

.auction-sim-section-title {
    color: #f6e7b6;
    font-size: 1rem;
    font-weight: 600;
    margin: 0 0 16px 0;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}

.auction-sim-history-table-wrap {
    overflow-x: auto;
}

.auction-sim-history-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.88rem;
    color: #d8ddea;
}

.auction-sim-history-table th,
.auction-sim-history-table thead th {
    background: #0a0e1a;
    color: #d4af37;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    padding: 10px 12px;
    text-align: left;
    border-bottom: 1px solid #2a3654;
    font-weight: 600;
}

.auction-sim-history-table td {
    padding: 10px 12px;
    border-bottom: 1px solid #1f2840;
}

.auction-sim-history-table tbody tr:hover {
    background: rgba(212,175,55,0.04);
}

.auction-sim-charts-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    margin-bottom: 28px;
}

.auction-sim-chart-card {
    background: #141b2e;
    border: 1px solid #2a3654;
    border-radius: 6px;
    padding: 22px;
    height: 320px;
    position: relative;
}

@media (max-width: 768px) {
    .auction-sim-container {
        padding: 16px;
    }
    .auction-sim-header {
        padding: 22px;
    }
    .auction-sim-header h1 {
        font-size: 1.35rem;
    }
    .auction-sim-meta-row {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
    }
    .auction-sim-design-panel .auction-sim-design-row {
        grid-template-columns: 1fr;
    }
    .auction-sim-charts-grid {
        grid-template-columns: 1fr;
    }
    .auction-sim-kpi-value {
        font-size: 1.6rem;
    }
}


/* ---- EQIL 2026-08-07: accessibility + end-of-run debrief ---- */
.auction-sim-container :focus-visible,
.auction-sim-container button:focus-visible,
.auction-sim-container input:focus-visible,
.auction-sim-container select:focus-visible {
    outline: 3px solid #f6e7b6;
    outline-offset: 2px;
    border-radius: 4px;
}

@media (prefers-reduced-motion: reduce) {
    .auction-sim-container *,
    .auction-sim-container *::before,
    .auction-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

.auction-sim-format-done {
    background: #1f3d2e;
    color: #a7f3d0;
    border-color: #34d399;
}

.auction-sim-completion {
    margin: 20px 0 8px;
}

.auction-sim-debrief {
    background: #131a2c;
    border: 1px solid #2a3654;
    border-radius: 10px;
    padding: 22px 24px;
    color: #c4cad6;
}

.auction-sim-debrief h3 {
    margin: 0 0 14px;
    color: #f6e7b6;
    font-size: 1.15rem;
    letter-spacing: 0.02em;
}

.auction-sim-debrief h4 {
    margin: 22px 0 10px;
    color: #f6e7b6;
    font-size: 0.95rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}

.auction-sim-debrief-score {
    display: flex;
    align-items: baseline;
    gap: 8px;
    flex-wrap: wrap;
    margin-bottom: 16px;
}

.auction-sim-debrief-num {
    font-size: 2.6rem;
    font-weight: 700;
    color: #d4af37;
    line-height: 1;
}

.auction-sim-debrief-den {
    font-size: 1.1rem;
    color: #8b95a8;
}

.auction-sim-debrief-band {
    margin-left: 10px;
    padding: 4px 12px;
    border: 1px solid #d4af37;
    border-radius: 999px;
    color: #f6e7b6;
    font-size: 0.85rem;
}

.auction-sim-debrief-stats {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 10px;
}

.auction-sim-debrief-stats li {
    background: #0f1524;
    border: 1px solid #2a3654;
    border-radius: 8px;
    padding: 10px 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 10px;
}

.auction-sim-debrief-stats li span {
    color: #8b95a8;
    font-size: 0.82rem;
}

.auction-sim-debrief-stats li strong {
    color: #f6e7b6;
    font-size: 1.05rem;
    white-space: nowrap;
}

.auction-sim-debrief-review {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    gap: 10px;
}

.auction-sim-debrief-review li {
    background: #0f1524;
    border-left: 4px solid #2a3654;
    border-radius: 6px;
    padding: 12px 14px;
}

.auction-sim-debrief-review li.is-ok {
    border-left-color: #34d399;
}

.auction-sim-debrief-review li.is-miss {
    border-left-color: #fbbf24;
}

.auction-sim-debrief-client {
    color: #e8ecf3;
    font-weight: 600;
    margin-bottom: 4px;
}

.auction-sim-debrief-verdict {
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 6px;
}

.auction-sim-debrief-review li.is-ok .auction-sim-debrief-verdict { color: #34d399; }
.auction-sim-debrief-review li.is-miss .auction-sim-debrief-verdict { color: #fbbf24; }

.auction-sim-debrief-pick,
.auction-sim-debrief-right {
    font-size: 0.88rem;
    color: #c4cad6;
}

.auction-sim-debrief-right { color: #a7f3d0; }

.auction-sim-debrief-why {
    margin-top: 6px;
    font-size: 0.86rem;
    line-height: 1.5;
    color: #8b95a8;
}

.auction-sim-debrief-insights {
    margin: 0;
    padding-left: 20px;
    line-height: 1.6;
}

.auction-sim-debrief-insights li {
    margin-bottom: 8px;
}

@media (max-width: 640px) {
    .auction-sim-debrief { padding: 16px; }
    .auction-sim-debrief-num { font-size: 2.1rem; }
}

