(function() {
    'use strict';

    class AuctionLabAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Auction Design Lab';
            this.version = '1.1.0';
            this._finished = false;
            this.N = 4;
            this.ROUNDS = [
                { format: 'english',    titleKey: 'r1_title', briefKey: 'r1_brief', inputKey: 'r1_input_label', equilibriumKey: 'r1_eq', anchorKey: 'anchor_english' },
                { format: 'dutch',      titleKey: 'r2_title', briefKey: 'r2_brief', inputKey: 'r2_input_label', equilibriumKey: 'r2_eq', anchorKey: 'anchor_dutch' },
                { format: 'firstprice', titleKey: 'r3_title', briefKey: 'r3_brief', inputKey: 'r3_input_label', equilibriumKey: 'r3_eq', anchorKey: 'anchor_firstprice' },
                { format: 'vickrey',    titleKey: 'r4_title', briefKey: 'r4_brief', inputKey: 'r4_input_label', equilibriumKey: 'r4_eq', anchorKey: 'anchor_vickrey' },
                { format: 'design',     titleKey: 'r5_title', briefKey: 'r5_brief', inputKey: 'r5_input_label', equilibriumKey: 'r5_eq', anchorKey: 'anchor_design' }
            ];
            this.CORRECT_DESIGN = {
                art:         'english',
                spectrum:    'spectrum-ascending',
                treasury:    'uniform',
                procurement: 'firstprice',
                ads:         'gsp'
            };
        }

        _randomValuation() {
            return Math.round(Math.random() * 100);
        }

        _getRound(period) {
            var idx = Math.max(0, Math.min((period || 1) - 1, this.ROUNDS.length - 1));
            return this.ROUNDS[idx];
        }

        _theoreticalRevenue() {
            return (this.N - 1) / (this.N + 1) * 100;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalSurplus: 0,
                    totalRevenue: 0,
                    totalWins: 0,
                    surplusHistory: [],
                    revenueHistory: [],
                    equilibriumRevenueHistory: [],
                    designScore: 0,
                    playerValuation: this._randomValuation(),
                    otherValuations: [this._randomValuation(), this._randomValuation(), this._randomValuation()]
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    bidAmount: 50,
                    design_art: '',
                    design_spectrum: '',
                    design_treasury: '',
                    design_procurement: '',
                    design_ads: ''
                };
            }
            var self = this;
            setTimeout(function() {
                self._updateBriefing(state);
                self._syncControlsFromDecisions(state);
            }, 80);
        }

        _syncControlsFromDecisions(state) {
            var d = (state && state.decisions) || {};
            var input = document.getElementById('bidInput');
            if (input && d.bidAmount != null && !isNaN(parseFloat(d.bidAmount))) {
                input.value = String(d.bidAmount);
            }
            var fields = ['art', 'spectrum', 'treasury', 'procurement', 'ads'];
            for (var i = 0; i < fields.length; i++) {
                var sel = document.getElementById('design_' + fields[i]);
                var v = d['design_' + fields[i]];
                if (sel && v != null) sel.value = String(v);
            }
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var round = this._getRound(state.currentPeriod);
            this._updateBriefing(state);

            if (round.format === 'design') {
                var fields = ['art', 'spectrum', 'treasury', 'procurement', 'ads'];
                for (var i = 0; i < fields.length; i++) {
                    var sel = document.getElementById('design_' + fields[i]);
                    if (sel) decisions['design_' + fields[i]] = sel.value;
                    if (!decisions['design_' + fields[i]]) {
                        window.mySimulation.uiManager.showNotification(
                            window.mySimulation.t('design_warning'), 'warning'
                        );
                        return false;
                    }
                }
                return true;
            }

            var input = document.getElementById('bidInput');
            if (input) decisions.bidAmount = parseFloat(input.value);

            if (isNaN(decisions.bidAmount) || decisions.bidAmount < 0 || decisions.bidAmount > 200) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('bid_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var round = this._getRound(period);
            var format = round.format;
            var N = this.N;
            var playerVal = ds.playerValuation;
            var otherVals = ds.otherValuations.slice();

            var results = {
                period: period,
                format: format,
                playerValuation: playerVal,
                otherValuations: otherVals.slice()
            };

            if (format === 'design') {
                var fields = ['art', 'spectrum', 'treasury', 'procurement', 'ads'];
                var score = 0;
                var details = {};
                for (var i = 0; i < fields.length; i++) {
                    var pick = d['design_' + fields[i]];
                    var correct = this.CORRECT_DESIGN[fields[i]];
                    var ok = pick === correct;
                    if (ok) score += 20;
                    details[fields[i]] = { pick: pick, correct: correct, ok: ok };
                }
                ds.designScore = score;
                ds.surplusHistory.push(score);
                ds.revenueHistory.push(score);
                ds.equilibriumRevenueHistory.push(100);
                ds.totalSurplus += score;

                results.designScore = score;
                results.designDetails = details;
                results.playerSurplus = score;
                results.price = null;
                results.equilibriumRevenue = 100;
                results.won = score >= 60;
                results.playerBid = null;
                results.equilibriumBid = null;

                ds.playerValuation = this._randomValuation();
                ds.otherValuations = [this._randomValuation(), this._randomValuation(), this._randomValuation()];

                var selfD = this;
                setTimeout(function() {
                    selfD._updateBriefing({ currentPeriod: period + 1, domainState: ds });
                }, 500);

                return results;
            }

            var playerBid = parseFloat(d.bidAmount);
            var competitorBids = [];
            var shadingFactor = (N - 1) / N;

            if (format === 'english' || format === 'vickrey') {
                for (var i = 0; i < otherVals.length; i++) {
                    var noise = 0.97 + Math.random() * 0.06;
                    competitorBids.push(otherVals[i] * noise);
                }
            } else {
                for (var i = 0; i < otherVals.length; i++) {
                    var noise = 0.92 + Math.random() * 0.16;
                    competitorBids.push(otherVals[i] * shadingFactor * noise);
                }
            }

            var bids = [{ who: 'you', val: playerVal, bid: playerBid }];
            for (var i = 0; i < competitorBids.length; i++) {
                bids.push({ who: 'B' + (i + 1), val: otherVals[i], bid: competitorBids[i] });
            }
            bids.sort(function(a, b) { return b.bid - a.bid; });

            var winner = bids[0];
            var price;
            if (format === 'vickrey' || format === 'english') {
                price = bids[1].bid;
            } else {
                price = winner.bid;
            }
            var won = winner.who === 'you';
            var playerSurplus = won ? Math.max(0, playerVal - price) : 0;

            var equilibriumBid;
            if (format === 'english' || format === 'vickrey') {
                equilibriumBid = playerVal;
            } else {
                equilibriumBid = playerVal * shadingFactor;
            }

            var equilibriumRevenue = this._theoreticalRevenue();

            ds.totalSurplus += playerSurplus;
            ds.totalRevenue += price;
            if (won) ds.totalWins += 1;
            ds.surplusHistory.push(playerSurplus);
            ds.revenueHistory.push(price);
            ds.equilibriumRevenueHistory.push(equilibriumRevenue);

            results.playerBid = playerBid;
            results.equilibriumBid = equilibriumBid;
            results.bidGap = playerBid - equilibriumBid;
            results.allBids = bids;
            results.winner = winner.who;
            results.price = price;
            results.equilibriumRevenue = equilibriumRevenue;
            results.won = won;
            results.playerSurplus = playerSurplus;

            ds.playerValuation = this._randomValuation();
            ds.otherValuations = [this._randomValuation(), this._randomValuation(), this._randomValuation()];

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1, domainState: ds });
            }, 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('totalSurplusDisplay', 'domainState.totalSurplus', function(v) {
                return '$' + Math.round(v);
            });
            uiManager.bind('totalRevenueDisplay', 'domainState.totalRevenue', function(v) {
                return '$' + Math.round(v);
            });
            uiManager.bind('totalWinsDisplay', 'domainState.totalWins');
            uiManager.bind('valuationDisplay', 'domainState.playerValuation', function(v) {
                return '$' + Math.round(v);
            });
        }

        getChartConfig() {
            return {
                surplusChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Player Surplus',
                            data: [],
                            backgroundColor: 'rgba(212,175,55,0.6)',
                            borderColor: '#d4af37',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Surplus per Round', color: '#f6e7b6', font: { size: 13 } },
                            legend: { labels: { color: '#c4cad6' } }
                        },
                        scales: {
                            y: { beginAtZero: true, ticks: { color: '#8b95a8' }, grid: { color: 'rgba(42,54,84,0.6)' } },
                            x: { ticks: { color: '#8b95a8' }, grid: { color: 'rgba(42,54,84,0.4)' } }
                        }
                    }
                },
                revenueChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Auction Revenue (actual)',
                                data: [],
                                borderColor: '#34d399',
                                backgroundColor: 'rgba(52,211,153,0.15)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2,
                                pointRadius: 4,
                                pointBackgroundColor: '#34d399'
                            },
                            {
                                label: 'RET benchmark',
                                data: [],
                                borderColor: '#fbbf24',
                                borderDash: [6, 6],
                                borderWidth: 2,
                                fill: false,
                                pointRadius: 0,
                                tension: 0
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Revenue vs. Revenue Equivalence Benchmark', color: '#f6e7b6', font: { size: 13 } },
                            legend: { labels: { color: '#c4cad6' } }
                        },
                        scales: {
                            y: { beginAtZero: true, ticks: { color: '#8b95a8' }, grid: { color: 'rgba(42,54,84,0.6)' } },
                            x: { ticks: { color: '#8b95a8' }, grid: { color: 'rgba(42,54,84,0.4)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var surplus = ds.surplusHistory || [];
            var revenue = ds.revenueHistory || [];
            var benchmark = ds.equilibriumRevenueHistory || [];
            var labels = surplus.map(function(_, i) { return 'R' + (i + 1); });
            return {
                surplusChart: {
                    labels: labels,
                    datasets: [{ data: surplus.slice() }]
                },
                revenueChart: {
                    labels: labels,
                    datasets: [
                        { data: revenue.slice() },
                        { data: benchmark.slice() }
                    ]
                }
            };
        }

        _bidAccuracy(r) {
            // Proximity of the submitted bid to the round equilibrium bid, relative to the
            // private valuation. 0 when the player is a quarter of their valuation away or
            // more, 1 when they bid the equilibrium exactly. This is the one measure in the
            // lab that reflects strategy rather than the luck of the valuation draw.
            if (!r || r.playerBid == null || r.equilibriumBid == null) return null;
            var denom = Math.max(Number(r.playerValuation) || 0, 20);
            var rel = Math.abs(Number(r.playerBid) - Number(r.equilibriumBid)) / denom;
            var acc = 1 - (rel / 0.25);
            if (acc < 0) acc = 0;
            if (acc > 1) acc = 1;
            return acc;
        }

        _composite(m) {
            // 45 pts bidding strategy, 40 pts auction design, 15 pts surplus captured.
            // Surplus is deliberately the smallest slice: expected equilibrium surplus over
            // four rounds is only about 20 on a 0-100 valuation scale and its variance is
            // large, so a player who bids the equilibrium correctly must not be graded down
            // by an unlucky draw.
            var bidPts = 45 * (m.bidAccuracy != null ? m.bidAccuracy : 0);
            var designPts = 40 * (Math.max(0, Math.min(100, m.designScore || 0)) / 100);
            var surplusPts = 15 * Math.min(1, Math.max(0, (m.totalSurplus || 0) / 40));
            var score = Math.round(bidPts + designPts + surplusPts);
            return Math.max(0, Math.min(100, score));
        }

        _band(score, bidAccuracy) {
            // Cap on the failure state: bidding your valuation in a first-price or Dutch
            // auction is the classic mistake this lab exists to correct, so a player who
            // never shades cannot reach the top band on design points alone.
            var acc = bidAccuracy != null ? bidAccuracy : 0;
            if (score >= 80 && acc >= 0.7) return 'master';
            if (score >= 60 && acc >= 0.4) return 'skilled';
            if (score >= 60) return 'skilled';
            return 'apprentice';
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var self = this;
            var totalSurplus = 0;
            var wins = 0;
            var designScore = 0;
            var designDetails = null;
            var biddingRounds = 0;
            var accSum = 0;
            var accCount = 0;
            var t = this._t();

            history.forEach(function(r) {
                if (!r.results) return;
                if (r.results.format === 'design') {
                    designScore = r.results.designScore || 0;
                    designDetails = r.results.designDetails || null;
                } else {
                    biddingRounds += 1;
                    totalSurplus += (r.results.playerSurplus || 0);
                    if (r.results.won) wins += 1;
                    var a = self._bidAccuracy(r.results);
