            var avgSurplus = biddingRounds > 0 ? totalSurplus / biddingRounds : 0;
            var bidAccuracy = accCount > 0 ? (accSum / accCount) : null;
            var score = this._composite({
                bidAccuracy: bidAccuracy,
                designScore: designScore,
                totalSurplus: totalSurplus
            });
            var band = this._band(score, bidAccuracy);

            var insights = [];
            if (bidAccuracy != null && bidAccuracy >= 0.75) {
                insights.push(t('ins_bid_high'));
            } else if (bidAccuracy != null && bidAccuracy < 0.4) {
                insights.push(t('ins_bid_low'));
            }
            if (designScore >= 80) {
                insights.push(t('ins_design_high'));
            } else if (designScore < 60) {
                insights.push(t('ins_design_low'));
            }
            if (biddingRounds > 0 && wins === 0) {
                insights.push(t('ins_no_wins'));
            } else if (avgSurplus < 5) {
                insights.push(t('ins_thin_surplus'));
            }
            if (totalSurplus >= 40) {
                insights.push(t('ins_strong_capture'));
            }
            if (!insights.length) {
                insights.push(t('ins_default'));
            }

            return {
                totalProfit: Math.round(totalSurplus),
                avgProfit: Math.round(avgSurplus),
                wins: wins,
                designScore: designScore,
                bidAccuracy: bidAccuracy != null ? Math.round(bidAccuracy * 100) : null,
                designDetails: designDetails,
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                performance: band,
                performanceKey: band,
                performanceLabel: t('perf_' + band),
                insights: insights
            };
        }

        _t() {
