                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            var html = '';
            html += '<div class="auction-sim-debrief">';
            html += '<h3>' + esc(t('done_title')) + '</h3>';
            html += '<div class="auction-sim-debrief-score">';
            html += '<span class="auction-sim-debrief-num">' + esc(s.overallScore != null ? s.overallScore : 0) + '</span>';
            html += '<span class="auction-sim-debrief-den">/100</span>';
            html += '<span class="auction-sim-debrief-band">' + esc(s.performanceLabel || '') + '</span>';
            html += '</div>';

            html += '<ul class="auction-sim-debrief-stats">';
            html += '<li><span>' + esc(t('done_bidding')) + '</span><strong>' + esc(s.bidAccuracy != null ? s.bidAccuracy + '%' : '-') + '</strong></li>';
            html += '<li><span>' + esc(t('done_design')) + '</span><strong>' + esc(s.designScore || 0) + '/100</strong></li>';
            html += '<li><span>' + esc(t('done_surplus')) + '</span><strong>$' + esc(s.totalProfit || 0) + '</strong></li>';
