        }

        getHint(state, results) {
            if (!results) return null;
            if (results.format === 'english') {
                if (results.playerBid != null && results.playerBid < results.playerValuation - 5) {
                    return window.mySimulation.t('hint_english_under');
                }
            }
            if (results.format === 'dutch' || results.format === 'firstprice') {
                if (results.equilibriumBid != null) {
                    if (results.playerBid > results.equilibriumBid + 8) return window.mySimulation.t('hint_overbid');
                    if (results.playerBid < results.equilibriumBid - 12) return window.mySimulation.t('hint_undershade');
                }
            }
            if (results.format === 'vickrey') {
                if (results.playerBid != null && Math.abs(results.playerBid - results.playerValuation) > 8) {
                    return window.mySimulation.t('hint_vickrey_truthful');
                }
            }
            if (results.format === 'design') {
                if (results.designScore >= 80) return window.mySimulation.t('hint_design_high');
                if (results.designScore < 60) return window.mySimulation.t('hint_design_low');
                return window.mySimulation.t('hint_design_mid');
            }
