        _updateBriefing(state) {
            var period = (state && state.currentPeriod) || 1;
            var finished = period > this.ROUNDS.length;
            if (finished) {
                this._finished = true;
                this._showRunComplete();
                return;
            }
            this._finished = false;
            this._hideRunComplete();
            var round = this._getRound(period);
            var t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);

            var briefEl = document.getElementById('roundBrief');
            if (briefEl) briefEl.innerHTML = t(round.briefKey);

            var anchorEl = document.getElementById('roundAnchor');
            if (anchorEl) anchorEl.textContent = t(round.anchorKey);

            var equilibriumEl = document.getElementById('equilibriumNote');
            if (equilibriumEl) equilibriumEl.innerHTML = t(round.equilibriumKey);

            var inputLabelEl = document.getElementById('bidInputLabel');
            if (inputLabelEl) inputLabelEl.textContent = t(round.inputKey);

            var biddingPanel = document.getElementById('biddingPanel');
            var designPanel = document.getElementById('designPanel');
            if (biddingPanel && designPanel) {
                if (round.format === 'design') {
                    biddingPanel.style.display = 'none';
                    designPanel.style.display = 'block';
                } else {
                    biddingPanel.style.display = 'block';
                    designPanel.style.display = 'none';
                }
            }

            var formatBadge = document.getElementById('formatBadge');
            if (formatBadge) {
                formatBadge.textContent = t('format_' + round.format);
                formatBadge.className = 'auction-sim-format-badge auction-sim-format-' + round.format;
            }
        }

        _showRunComplete() {
            var t = this._t();
            var ids = ['biddingPanel', 'designPanel'];
            for (var i = 0; i < ids.length; i++) {
                var p = document.getElementById(ids[i]);
                if (p) p.style.display = 'none';
            }
            var row = document.getElementById('actionRow');
            if (row) row.style.display = 'none';
            var submit = document.getElementById('nextPeriodBtn');
            if (submit) submit.disabled = true;
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t('run_complete_title');
            var briefEl = document.getElementById('roundBrief');
            if (briefEl) briefEl.textContent = t('run_complete_body');
            var eqEl = document.getElementById('equilibriumNote');
            if (eqEl) eqEl.textContent = '';
            var anchorEl = document.getElementById('roundAnchor');
            if (anchorEl) anchorEl.textContent = t('anchor_design');
            var badge = document.getElementById('formatBadge');
            if (badge) {
                badge.textContent = t('run_complete_badge');
                badge.className = 'auction-sim-format-badge auction-sim-format-done';
            }
            var host = document.getElementById('completionPanel');
            if (host) {
                var sim = window.mySimulation;
                var summ = (sim && sim.lastSummary) ? sim.lastSummary
                         : (sim && sim.adapter && sim.state ? this.getPerformanceSummary(sim.state.history || []) : null);
                if (summ) host.innerHTML = this.formatCompletionMessage(summ);
                host.style.display = 'block';
            }
        }

        _hideRunComplete() {
            var host = document.getElementById('completionPanel');
            if (host) host.style.display = 'none';
            var row = document.getElementById('actionRow');
            if (row) row.style.display = '';
        }

